/**
 * Test flow for lookupAttachment action
 * Demonstrates looking up an attachment
 */

import { action, Flow, wfa, trigger } from '@servicenow/sdk/automation'

export const testLookupAttachment = Flow(
    {
        $id: Now.ID['test_lookup_attachment_flow'],
        name: 'Test Lookup Attachment',
        description: 'Tests the lookupAttachment core action',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_lookup_attachment_trigger'] },
        {
            table: 'incident',
            condition: 'active=true',
            run_flow_in: 'background',
        }
    ),
    (_params) => {
        const result = wfa.action(
            action.core.lookupAttachment,
            { $id: Now.ID['test_lookup_attachment_action'] },
            {
                source_record: wfa.dataPill(_params.trigger.current.sys_id, 'reference'),
                file_name: 'test.txt',
            }
        )

        wfa.action(
            action.core.log,
            { $id: Now.ID['test_lookup_attachment_log'] },
            {
                log_level: 'info',
                log_message: `lookupAttachment outputs: attachment=${wfa.dataPill(result.parameter, 'reference')}, found=${wfa.dataPill(result.parameter1, 'boolean')}`,
            }
        )
    }
)
